import{b as d,O as a,g as e,j as r}from"./chunks/framework.DSt9LnBW.js";const b=JSON.parse('{"title":"Agent 怎么评、怎么标、怎么改","description":"本文把评估、标注、优化收成一条闭环：先说清测的是哪一类 Agent，再讲评什么、题库怎么标、失败了改哪一层。知识库问答那一套（评测集五类样本、四档评分、检索层硬断言）已经写过，见大模型问答测试怎么做。这里不重复那套题库，只补 Agent 多出来的那一截。日常说的 Agent，范围可以大到自动驾驶。这里只谈软件里的 LLM Agent：能读当前状态、决定下一步、调用工具或知识、必要时多轮，直到任务结束或明确失败。","frontmatter":{"date":"2026-07-25T00:00:00.000Z","tags":["Agent","评估","标注","优化"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/ai/agent-eval-annotate-optimize/index.md","filePath":"个人博客/AI/1.Agent怎么评怎么标怎么改.md","lastUpdated":1791443863000}'),n={name:"blog/ai/agent-eval-annotate-optimize/index.md"};function s(o,t,l,i,p,h){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="agent-怎么评、怎么标、怎么改" tabindex="-1">Agent 怎么评、怎么标、怎么改 <a class="header-anchor" href="#agent-怎么评、怎么标、怎么改" aria-label="Permalink to &quot;Agent 怎么评、怎么标、怎么改&quot;">​</a></h1><p>本文把评估、标注、优化收成一条闭环：先说清测的是哪一类 Agent，再讲评什么、题库怎么标、失败了改哪一层。知识库问答那一套（评测集五类样本、四档评分、检索层硬断言）已经写过，见 <a href="/blog/testing/llm-qa-testing/">大模型问答测试怎么做</a>。这里不重复那套题库，只补 <strong>Agent 多出来的那一截</strong>。</p><h2 id="先划界-这篇文章在测什么" tabindex="-1">先划界：这篇文章在测什么 <a class="header-anchor" href="#先划界-这篇文章在测什么" aria-label="Permalink to &quot;先划界：这篇文章在测什么&quot;">​</a></h2><p>日常说的 Agent，范围可以大到自动驾驶。这里只谈 <strong>软件里的 LLM Agent</strong>：能读当前状态、决定下一步、调用工具或知识、必要时多轮，直到任务结束或明确失败。</p><p>和另外两件事分开：</p><table tabindex="0"><thead><tr><th></th><th>测什么</th><th>失败长什么样</th></tr></thead><tbody><tr><td>单轮问答 / RAG</td><td>这一句是否可接受、能否溯源</td><td>答错、编造、答非所问</td></tr><tr><td><strong>Agent</strong></td><td>目标有没有达成，路径是否可接受</td><td>工具选错、参数错、死循环、半途而废、越权调用</td></tr><tr><td>模型训练实验</td><td>超参、loss、版本能不能复现</td><td>那是训练侧的事，不是线上 Agent 验收</td></tr></tbody></table><p>推荐、客服、测试助手都可以做成 Agent，但验收口径不要跟着行业词走，跟着 <strong>「有没有工具、有没有多步」</strong> 走。没有工具、一问一答，用问答那篇就够。</p><h2 id="评什么-五维里先抓住能拦发布的" tabindex="-1">评什么：五维里先抓住能拦发布的 <a class="header-anchor" href="#评什么-五维里先抓住能拦发布的" aria-label="Permalink to &quot;评什么：五维里先抓住能拦发布的&quot;">​</a></h2><p>指标可以列很长。真要进发布门槛，先按「这次失败会不会让人把系统关掉」收口。五个方向都留着，权重不一样。</p><table tabindex="0"><thead><tr><th>方向</th><th>问的是</th><th>发布时优先看</th></tr></thead><tbody><tr><td><strong>功能</strong></td><td>任务做完了没有，质量过不过线</td><td>目标达成率、工具选对了没有、参数对不对</td></tr><tr><td><strong>性能</strong></td><td>够不够快、贵不贵</td><td>端到端耗时、Token / 调用成本</td></tr><tr><td><strong>可靠</strong></td><td>同一类题会不会这次过、下次挂</td><td>首次成功率、错误类型分布</td></tr><tr><td><strong>安全</strong></td><td>会不会被带跑、泄数据</td><td>注入拦截、越权调用、敏感信息是否出站</td></tr><tr><td><strong>体验</strong></td><td>人能不能用下去</td><td>多轮是否还记得上下文；先做功能，再谈 NPS</td></tr></tbody></table><p>功能里 Agent 比问答多出来的，是 <strong>工具这一层</strong>：</p><ul><li>该调的工具调了没有，不该调的有没有乱调</li><li>参数是否满足约定（缺字段、类型错、枚举越界）</li><li>多个工具的顺序有没有把后续步骤的前提破坏掉（先删后查、先提交后确认）</li></ul><p>性能要把耗时拆开：模型「想」的时间、工具执行的时间、整段端到端。只报一个总时长，优化时不知道该砍提示词还是砍接口。成本同理：模型 Token 和外部 API 是两笔账。</p><p>可靠不要只报「成功率」。Agent 常见的挂法不一样：超时、工具 4xx、自己陷入重试、输出不是约定的 JSON。按类型计数，后面的优化才知道改哪一层。</p><p>评估怎么做，仍然是四条路，和问答篇一致，只是对象从「一段话」变成「一次轨迹」：</p><table tabindex="0"><thead><tr><th>方法</th><th>适合</th></tr></thead><tbody><tr><td>离线、带标准轨迹或标准结果</td><td>回归、对比版本</td></tr><tr><td>线上抽样 / A/B</td><td>看真实用户会怎么用</td></tr><tr><td>规则打分（格式、Schema、是否调用了某工具）</td><td>能自动化的部分，优先自动化</td></tr><tr><td>更强模型打分（LLM-as-a-Judge）</td><td>开放表述；要抽检，防止裁判自己编</td></tr></tbody></table><p>能写成规则的，不要交给裁判模型。工具是否调用、JSON 能不能解析、是否碰到禁止的工具名，用代码判。裁判模型用在「这步解释通不通、最终对用户是否有用」这种灰色地带。</p><h2 id="标什么-题库要带成功标准和路径" tabindex="-1">标什么：题库要带成功标准和路径 <a class="header-anchor" href="#标什么-题库要带成功标准和路径" aria-label="Permalink to &quot;标什么：题库要带成功标准和路径&quot;">​</a></h2><p>评估和优化都坐在题库上。题库差，后面的分数和改动都是空的。</p><p>来源按价值大致是：真实用户日志（最高）、历史工单或客服会话、人工构造的边缘和对抗、模型合成后再人工过目。合成可以补数量，不能代替真实失败。</p><p>一条样本建议至少有：</p><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td>输入</td><td>用户原话或系统触发条件</td></tr><tr><td>成功标准</td><td>怎样才算过：最终状态、必须调用的工具、禁止调用的工具、输出 Schema</td></tr><tr><td>标准结果或标准路径</td><td>理想回答，或可接受的工具顺序（允许列出等价路径）</td></tr><tr><td>中间轨迹（有工具时尽量要）</td><td>实际或期望的工具名、参数、顺序</td></tr></tbody></table><p>成功标准要写到能自动判的程度。只写「回答专业」无法回归。能写成「返回的 <code>orderId</code> 非空且库存减少 1」就写到这一层。</p><p>题库内部要拆成两类，不要混在一个准确率里取平均：</p><table tabindex="0"><thead><tr><th></th><th><strong>能力题</strong></th><th><strong>回归题</strong></th></tr></thead><tbody><tr><td>目的</td><td>探上限：新工具、更长流程、更绕的指令</td><td>防倒退：以前会的，改完还要会</td></tr><tr><td>失败含义</td><td>能力还不够，不一定挡发布</td><td>往往要挡发布</td></tr><tr><td>怎么维护</td><td>可以随版本加</td><td>失败过的真实案例优先固化进来</td></tr></tbody></table><p>条数不要先定一个「统计意义」整数。先保证 <strong>每类已知失败至少有题</strong>，回归集能挡住上一次修过的洞。题太少，分数会跟着一两道题跳——这个道理和压测里 P95 后面站着几个人是同一类问题：少了，线就被偶然事件带着走。</p><h2 id="用什么看一次-agent-跑完了什么" tabindex="-1">用什么看一次 Agent 跑完了什么 <a class="header-anchor" href="#用什么看一次-agent-跑完了什么" aria-label="Permalink to &quot;用什么看一次 Agent 跑完了什么&quot;">​</a></h2><p>Agent 评估首先要能 <strong>把一次运行展开成轨迹</strong>：哪一轮模型输出、调了哪个工具、入参出参、最终给用户什么。看不到轨迹，就只能给终态打分，优化只能猜。</p><p>开源里，偏应用监控、带追踪和人工标注的，以 Langfuse 这类产品为代表：记链路、把自动分和人工标写回同一条轨迹、数据集能做版本。MLflow、W&amp;B 更擅长训练实验、超参和模型注册，和「这次 Agent 跑偏在第几步」不是同一层问题。商业侧还有偏质量漂移、根因分析的可观测平台，团队大了再选型，不作为入门门槛。</p><p>选型问三句就够：</p><ol><li>一次失败能不能点开看到工具调用？</li><li>人工标的对错能不能挂回同一条记录？</li><li>这批题下次还能用同一份跑？</li></ol><p>这三句都「能」，框架可以换，闭环已经立住了。</p><h2 id="怎么改-对着失败类型下手" tabindex="-1">怎么改：对着失败类型下手 <a class="header-anchor" href="#怎么改-对着失败类型下手" aria-label="Permalink to &quot;怎么改：对着失败类型下手&quot;">​</a></h2><p>优化要基于评估，盯 <strong>高频失败</strong>，不要每次全盘改提示词。</p><table tabindex="0"><thead><tr><th>失败长什么样</th><th>优先改哪里</th></tr></thead><tbody><tr><td>格式不稳、漏字段、角色飘</td><td>提示词：角色、输出约束、少样本；必要时思维链</td></tr><tr><td>工具选错、参数乱、重复调用</td><td>工具描述和 Schema；减少一次暴露的工具数量</td></tr><tr><td>业务规则过期、事实错</td><td>知识库或检索，而不是把事实写进提示词里硬背</td></tr><tr><td>长流程做到一半忘了前面</td><td>拆成小域 Agent，或加记忆 / 状态，避免一条上下文塞所有子任务</td></tr><tr><td>又慢又贵</td><td>缓存高频查询、能异步的步骤异步、模型侧再考虑量化或蒸馏</td></tr><tr><td>偶发超时、外部 5xx</td><td>重试和降级策略；不要把基础设施抖动记成「模型变笨」</td></tr></tbody></table><p>「小域专精」说白了：一个 Agent 既做退款又做推荐又做查物流，上下文会互相污染。按子任务拆开，评估也可以按子任务出分，定位会快很多。</p><p>线上仍要看延迟、错误率、用户是否把任务点完。这些数是发现「又出新失败类型」的来源，新类型再进回归题库。是否上强化学习或大规模重训，是后一步；多数业务 Agent 的第一轮优化，停在提示词、工具契约和知识更新就够。</p><h2 id="一条能反复跑的闭环" tabindex="-1">一条能反复跑的闭环 <a class="header-anchor" href="#一条能反复跑的闭环" aria-label="Permalink to &quot;一条能反复跑的闭环&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实失败 / 日志 → 标成题（成功标准 + 轨迹）</span></span>
<span class="line"><span>        → 离线重放，规则能判的用规则</span></span>
<span class="line"><span>        → 分数和失败类型进报告</span></span>
<span class="line"><span>        → 只改对应那一层</span></span>
<span class="line"><span>        → 回归题必须过，能力题用来看有没有变强</span></span></code></pre></div><p>和问答篇的关系可以记成：问答测 <strong>终态那句话</strong>；Agent 还要测 <strong>怎么走到终态</strong>。质量评测和性能压测仍然分开——压测看容量和 TTFT，评测看对错和路径，不要塞进同一个脚本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Agent 验收比问答多一层：<strong>工具是否用对、路径是否可接受</strong>，只看最终回复会漏判。</li><li>发布门槛先看功能（含工具）和安全；性能、体验随后跟上，但耗时和成本要能拆开。</li><li>题库要带成功标准；能力题探上限，回归题防倒退，不要混成一个准确率。</li><li>先有轨迹再谈优化；改哪一层由失败类型决定，不要默认全改提示词。</li></ul>`,42)])])}const c=d(n,[["render",s]]);export{b as __pageData,c as default};
